package com.lyra.studio; import android.content.Context; import android.graphics.Rect; import android.view.View; import android.view.ViewTreeObserver; import android.webkit.WebSettings; import android.webkit.WebView; import android.webkit.WebViewClient; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; @DesignerComponent(version = 1, description = "Um WebViewer customizado que se adapta ao teclado virtual, não permitindo que o conteúdo seja coberto.", category = ComponentCategory.EXTENSION, nonVisible = false, iconName = "images/web.png") @SimpleObject(external = true) public class AdaptiveWebViewer extends AndroidViewComponent { private WebView webView; private Context context; public AdaptiveWebViewer(ComponentContainer container) { super(container); context = container.$context(); webView = new WebView(context); /* Configurações básicas do WebView */ WebSettings webSettings = webView.getSettings(); webSettings.setJavaScriptEnabled(true); webSettings.setDomStorageEnabled(true); webView.setWebViewClient(new WebViewClient()); /* Adiciona o WebView ao container do App Inventor */ container.$add(this); /* Lógica para adaptar ao teclado */ setupKeyboardListener(); } @Override public View getView() { return webView; } private void setupKeyboardListener() { final View rootView = ((android.app.Activity) context).findViewById(android.R.id.content); rootView.getViewTreeObserver().addOnGlobalLayoutListener(new ViewTreeObserver.OnGlobalLayoutListener() { @Override public void onGlobalLayout() { Rect r = new Rect(); rootView.getWindowVisibleDisplayFrame(r); int screenHeight = rootView.getRootView().getHeight(); /* Calcula o tamanho do teclado */ int keypadHeight = screenHeight - r.bottom; /* Se o teclado ocupa mais de 15% da tela, está aberto, então aplicamos um padding */ if (keypadHeight > screenHeight * 0.15) { webView.setPadding(0, 0, 0, keypadHeight); } else { webView.setPadding(0, 0, 0, 0); } } }); } @SimpleFunction(description = "Carrega uma URL no WebViewer customizado.") public void IrParaUrl(String url) { webView.loadUrl(url); } @SimpleProperty(description = "Retorna a URL atual.") public String UrlAtual() { return webView.getUrl(); } }